    "descriptionAr": "Red Bull Energy Drink, 250ml\nWhen to Drink\nRed Bull Energy Drink is appreciated worldwide by top athletes, students, and in highly demanding professions as well as during long drives.\n\nWhat's Inside the Can\nCaffeine: Caffeine was already known by ancient civilizations. They consumed it from natural sources like tea, coffee, cacao beans and cola nuts and appreciated its stimulating effects on the human body.\n\nTaurine: Taurine is an amino acid, naturally occurring in the human body and present in the daily diet. It is involved in a wide range of biological processes.\n\nB-group vitamins: Vitamins are essential micronutrients that are required for maintaining normal body functions.\n\nSugars: Red Bull Energy Drink is made with sugar sourced from sugar beets.\n\nAlpine Water: Naturally, water is a main ingredient of Red Bull.\n\nFlavor: Red Bull Energy Drink 250ml, Single can.\n\nRed Bull Energy Drink's special formula contains ingredients of high quality: Caffeine, Taurine, B-Group Vitamins, Sugars, Alpine Water\n\nOne 250 ml can of Red Bull Energy Drink contains 80 mg of caffeine, about the same amount as in a cup of home-brewed coffee.\n\nThe number of sugars in a can of Red Bull Energy Drink is comparable to the level of sugars in an equivalent amount of apple or orange juice -11 g per 100 ml.\n\nRed Bull Gives You Wings\n\nInspired by functional drinks from the Far East, Dietrich Mateschitz founded Red Bull in the mid-1980s. He developed a new product and a unique marketing concept and launched Red Bull Energy Drink on April 1, 1987, in Austria.\n\nA brand-new product category -Energy Drinks -was born.",
