    "descriptionAr": "Product Description:\n\nImmerse yourself in the allure of the tropics with the Eva Coconut Scent Body Lotion for Normal Skin, 370ml. Carefully crafted for everyday use, this body lotion is a sumptuous treat for your skin with its lightweight, non-greasy formula that absorbs quickly, ensuring you get the hydration you need without that heavy feeling. This nourishing lotion features a beautifully entrancing coconut scent that transports you to a beachside paradise with every application. Ideal for normal skin types, it will leave your skin feeling soft, silky, and utterly pampered, with a gorgeous glow that lasts all day. \n\nHow to Use:\n\n- Start with freshly cleansed skin. \n- Take a generous amount of the Eva Coconut Scent Body Lotion onto your palm.\n- Gently massage the lotion over your body in a circular motion, until fully absorbed.\n- Pay special attention to areas like knees and elbows which tend to be drier.\n- For optimal hydration, apply after bathing or showering while the skin is still damp. \n\nStorage Instructions:\n\n- Keep the lotion in a cool, dry place away from direct sunlight.\n- Ensure the lid is tightly closed after every use to retain its maximum efficacy and scent. \n- Avoid storing in extremely hot or cold environments as it might affect the texture and viscosity of the lotion.\n- Store out of reach of children.\n\nIngredients:\n\n- Aqua (deionized water)\n- Cocos Nucifera (Coconut) Oil \n- Glycerin\n- Stearic Acid\n- Cetyl Alcohol\n- Fragrance (Coconut)\n- Phenoxyethanol\n- Ethylhexylglycerin",
