    "descriptionAr": "Lord Extra double edge razor blades \nHighest quality blades made to fit different double edge safety razors \nEach blade is individually wax paper wrapped\n\nHow to use:\n\nPrepare your skin: Wash your face with warm water to soften the hair and open your pores. Apply a generous amount of shaving cream or gel to the area you will shave. \nHold the razor: Grip the handle of the disposable razor firmly. \nShave with the grain: Use short, gentle strokes in the direction your hair is growing. Avoid pressing down too hard, as this can cause irritation or nicks. \nRinse the blade: After each stroke or two, rinse the blade under warm water to remove hair and shaving cream. \nRe-apply cream: If you run out of lather, re-apply more shaving cream before continuing. \nRinse your face: Once you are finished, rinse your face with cool water to remove any remaining cream and close your pores. \nPat dry: Gently pat your face dry with a clean towel. Avoid rubbing, which can irritate the skin.",
